    match &task.compiled {
        Some(compiled) => {
            let prompt = div()
                .id(("compiled-prompt", ix))
                .min_w_0()
                .child(markdown_view(
                    MarkdownKey {
                        kind: MarkdownKind::Prompt,
                        table: ix,
