            assert_eq!(chat_input.read(cx).editor.read(cx).value().as_ref(), "");
            assert!(editor_focused(window, cx));
        })
        .unwrap();
        cx.run_until_parked();
        assert_eq!(submitted.borrow().as_slice(), ["Fix it"]);
